def multiset_overlap(left: list[int], right: list[int]) -> list[int]:
    counts={}
    for x in right: counts[x]=counts.get(x,0)+1
    out=[]
    for x in left:
        if counts.get(x,0)>0: out.append(x);counts[x]-=1
    return out
